using System;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;using UnityEngine.UI;
namespace CTXD.Client.Features.Social { public sealed class ChatPanel:MonoBehaviour { static ChatPanel _open;ApiClient _api;Action<string> _status;RectTransform _window;ChatHistoryResponse _history;BlacklistResponse _blacklist;string _type="COUNTRY";string _to="";string _message="";public static ChatPanel Open(RectTransform host,ApiClient api,Action<string> status){if(_open!=null){_= _open.Refresh();return _open;}var go=new GameObject("ChatPanel");go.transform.SetParent(host,false);var p=go.AddComponent<ChatPanel>();_open=p;p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}public static void RefreshOpenFromPush(){if(_open!=null)_= _open.Refresh();}void OnDestroy(){if(_open==this)_open=null;}void Build(){var blocker=LegacyUiFactory.Panel(transform,"ChatBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.72f));_window=LegacyUiFactory.PixelPanel(blocker,"ChatWindow",180,85,900,570,new Color(.045f,.03f,.018f,1));}async Task Refresh(){try{_history=await _api.GetChatAsync(_type);_blacklist=await _api.GetBlacklistAsync();Draw();}catch(Exception ex){_status(ex.Message);}}void Draw(){LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"CHAT · "+_type,23,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),280,14,340,35);LegacyUiFactory.PixelButton(_window,"Close",805,18,70,28,()=>Destroy(gameObject));LegacyUiFactory.PixelButton(_window,"Country",25,18,105,28,()=>{_type="COUNTRY";_=Refresh();});LegacyUiFactory.PixelButton(_window,"Private",135,18,105,28,()=>{_type="ONE2ONE";_=Refresh();});var rows=_history?.items??Array.Empty<ChatMessageView>();Array.Reverse(rows);var start=Math.Max(0,rows.Length-10);for(var i=start;i<rows.Length;i++){var m=rows[i];LegacyUiFactory.PixelLabel(_window,m.from+(string.IsNullOrEmpty(m.to)?"":" → "+m.to)+": "+m.message,14,TextAnchor.MiddleLeft,Color.white,30,65+(i-start)*35,650,31);}var blocked=_blacklist?.items??Array.Empty<BlacklistView>();for(var i=0;i<Math.Min(5,blocked.Length);i++){var b=blocked[i];LegacyUiFactory.PixelLabel(_window,b.name,13,TextAnchor.MiddleLeft,new Color(.9f,.55f,.4f),700,70+i*40,100,25);LegacyUiFactory.PixelButton(_window,"Unblock",800,70+i*40,75,25,async()=>{await _api.RemoveBlacklistAsync(b.id);await Refresh();});}var to=LegacyUiFactory.Input(_window,"Recipient",new Vector2(.035f,.12f),new Vector2(.25f,.18f));to.text=_to;var msg=LegacyUiFactory.Input(_window,"Message",new Vector2(.27f,.12f),new Vector2(.78f,.18f));msg.text=_message;LegacyUiFactory.PixelButton(_window,"Send",720,465,120,32,async()=>{try{_to=to.text.Trim();_message=msg.text.Trim();await _api.SendChatAsync(_type,_to,_message);_message="";await Refresh();}catch(Exception ex){_status(ex.Message);}});LegacyUiFactory.PixelButton(_window,"Block",720,510,120,28,async()=>{try{await _api.AddBlacklistAsync(to.text.Trim());await Refresh();}catch(Exception ex){_status(ex.Message);}});}}
}
